styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  column-gap: var(--g-gap);
  align-items: start;
  /* padding-top: calc( var(--h6) * 2 ); */
  padding-bottom: calc(var(--h1) * 2);
}

section[data-skill-hub] .controls {
  grid-column-start: 1;
  grid-column-end: 7;
  display: flex;
  justify-content: center;
  gap: var(--g-gap);

  position: sticky;
  z-index: 10;
  top: calc(var(--h6) * 5);
}

section[data-skill-hub] .control-group {
  padding: var(--g-gap) calc(var(--g-gap) * 2) var(--g-gap) var(--g-gap);
  border-radius: var(--mm);
  background-color: rgba(var(--c-black-rgb), 0.6);
  background-image: linear-gradient(0deg, rgba(var(--c-grey-dark-rgb), 0.2));
  backdrop-filter: blur(1rem);
  border: 1px solid rgba(var(--c-grey-dark-rgb), 0.4);

  box-shadow: 0 1rem 2rem rgba(var(--c-black-rgb), 0.4);
}
section[data-skill-hub] .control-group > span {
  display: block;
  margin-bottom: var(--mm);
  color: #f4c7a7;
  border-bottom: 2px solid #f4c7a740;
}

section[data-skill-hub] .button-group {
  display: flex;
  gap: calc(var(--g-gap) / 2);
  padding: 0.1rem;
  background-color: rgba(var(--c-grey-dark-rgb), 1);
  border-radius: calc(var(--mm) - var(--g-gap) + 0.05rem);
}
section[data-skill-hub] .button-group button {
  padding: 0.05rem var(--g-gap);
  /* background-color: rgba( var(--c-grey-dark-rgb),0.2 ); */
  border-radius: calc(var(--mm) - var(--g-gap));
}
section[data-skill-hub] .button-group button.-active {
  background-color: var(--c-black);
  color: #f4c7a7;
}

section[data-skill-hub] .checkbox-wrap {
  display: flex;
  justify-content: flex-start;
  align-items: center;
}

section[data-skill-hub] .checkbox-wrap label {
  padding: 0.1rem 0;
  margin-left: var(--g-gap);
  color: var(--c-white);
  transform: translateZ(0);
  opacity: 0.4;
  transition: opacity 0.6s var(--f-cubic), color 0.6s var(--f-cubic);
}
section[data-skill-hub] .checkbox-wrap input:checked ~ label {
  color: #f4c7a7;
  opacity: 1;
}

section[data-skill-hub] .masonry-grid {
  grid-column-start: 1;
  grid-column-end: 7;
  grid-row-start: 2;
  margin-top: calc(var(--h1) * 2);
  position: relative;
}
section[data-skill-hub] .masonry-item {
  padding-bottom: var(--mm);
  will-change: transform, width, height;
}

section[data-skill-hub] .masonry-item figure {
  width: 100%;
  height: 100%;
}
section[data-skill-hub] .masonry-item figure img {
  width: 100%;
  height: 100%;
  transform: translateZ(0);
  object-fit: cover;
}
section[data-skill-hub] .masonry-item span {
  display: block;
  color: #f4c7a7;
  margin-top: var(--g-gap);
  opacity: 1;
  transition: opacity 0.3s ease;
}

@media (max-width: 1024px) {
  section[data-skill-hub] .button-group button.-not-on-m {
    display: none;
  }
}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w {
    grid-template-columns: repeat(14, 1fr);
  }
  section[data-skill-hub] .controls {
    grid-column-start: 4;
    grid-column-end: 12;
  }

  section[data-skill-hub] .masonry-grid {
    grid-column-start: 3;
    grid-column-end: 13;
  }
  section[data-skill-hub] .masonry-grid span {
    transform: translateZ(0);
    opacity: 1;
    transition: opacity 1.5s var(--easing-function-2);
  }
}

scripts.tutorial:
setTimeout(() => {
  const grid = document.getElementById('masonry-grid');
  const colButtons = document.querySelectorAll('#col-controls button');
  const modeButtons = document.querySelectorAll('#mode-controls button');
  const stringTune = window.StringTuneContext;

  const fixedSpeed = 1200;
  const randomNumber = (min, max) => {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  };

  const setActive = (buttons, value, attr) => {
    buttons.forEach((btn) => {
      if (btn.getAttribute(attr) == value) {
        btn.classList.add('-active');
      } else {
        btn.classList.remove('-active');
      }
    });
  };

  colButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const cols = parseInt(btn.getAttribute('data-cols'));
      setActive(colButtons, cols, 'data-cols');
      if (stringTune) {
        stringTune.emit('masonry:update:gallery', { cols: cols });
      }
    });
  });

  modeButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const mode = btn.getAttribute('data-mode');
      setActive(modeButtons, mode, 'data-mode');
      if (grid) {
        grid.setAttribute('string-masonry-mode', mode);
      }
      if (stringTune) {
        stringTune.emit('masonry:update:gallery', { mode: mode });
      }
    });
  });

  const timingCheckbox = document.getElementById('masonry-random-timing-toggle');

  const updateTiming = () => {
    const isRandom = timingCheckbox?.checked;
    const items = document.querySelectorAll('.masonry-item');

    items.forEach((item, i) => {
      let duration = fixedSpeed.toString();
      if (isRandom) {
        const randomSpeed = randomNumber(1200, 3000);
        duration = randomSpeed.toString();
      }

      item.setAttribute('string-masonry-position-time', duration);
      item.setAttribute('string-masonry-size-time', duration);
    });

    if (stringTune) {
      stringTune.emit('masonry:update:gallery', {});
    }
  };

  stringTune.on('masonry:shuffle:start', () => {
    document.getElementById('masonry-grid').classList.add('shuffling');
  });
  stringTune.on('masonry:shuffle:end', () => {
    document.getElementById('masonry-grid').classList.remove('shuffling');
    // setTimeout(() => {
    //   stringTune.scrollTo(0);
    // }, 30);
  });

  if (timingCheckbox) {
    timingCheckbox.checked = false;
    timingCheckbox.disabled = false;
    timingCheckbox.addEventListener('change', updateTiming);
    updateTiming();
  }

  setActive(colButtons, '3', 'data-cols');
  setActive(modeButtons, 'manual', 'data-mode');


  stringTune.emit('masonry:update:gallery', { cols: 3 });

  if (grid) {
    grid.setAttribute('string-masonry-mode', 'manual');
  }
}, 3);
